import { MeshStandardNodeMaterial } from 'three/webgpu';
import * as THREE from 'three/webgpu';
import { texture, uv, vec3, color } from 'three/tsl';
import gsap from 'gsap';
import { getFontAtlas } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-card-2-label';
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6, height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const material = new MeshStandardNodeMaterial();
  material.colorNode = texture(map, uv());
  material.roughness = 0.55;
  material.metalness = 0.4;
  material.color = color(0x16161d);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'journal-card-2-plane';
  group.add(mesh);

  // Text: headline "Journal 2"
  let textMesh = null;
  const fontAtlas = ctx.fontAtlas || (ctx.getFontAtlas ? ctx.getFontAtlas('display') : null);
  const atlas = fontAtlas || getFontAtlas?.('Lora');
  if (atlas && atlas.createTextMesh) {
    textMesh = atlas.createTextMesh('Journal 2', {
      size: 0.34,
      color: '#e8ecf2',
      weight: 400,
      font: 'Lora',
    });
    textMesh.position.set(-width / 2 + 0.25, 0, 0.01);
    group.add(textMesh);
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (fn) fn(group, primitive.params);
    }
  }

  // Interaction state
  let hoverTl = null;
  let pressTl = null;
  const baseY = group.position.y;

  const onHover = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onHoverOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onClick = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline()
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out' });

    if (group.userData.emit) {
      group.userData.emit('hub-journal.select', { source: 'hub-journal-card-2-label' });
    }
  };

  group.userData.handlers = {
    onHover,
    onHoverOut,
    onClick,
  };

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    if (textMesh) {
      textMesh.geometry?.dispose();
      textMesh.material?.dispose();
    }
  };

  return group;
}
